  const int TILE = 64;
  int i, j, ii, jj;

  for (jj = 0; jj < _PB_N; jj += TILE) {
    #pragma omp parallel for private(j)
    for (i = 0; i < _PB_N; i++) {
      for (j = jj; j < jj + TILE && j < _PB_N; j++) {
        x1[i] = x1[i] + A[i][j] * y_1[j];
      }
    }
  }

  #pragma omp parallel for private(i, j)
  for (ii = 0; ii < _PB_N; ii += TILE) {
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE temp = y_2[j];
      #pragma omp simd
      for (i = ii; i < ii + TILE && i < _PB_N; i++) {
        x2[i] = x2[i] + A[j][i] * temp;
      }
    }
  }
#pragma endscop
